INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES
(64, 'El Spa de Malvaviscos', 'Tras una larga noche de travesuras, nuestro elfo ha decidido tomarse un merecido descanso. Se encuentra sumergido en una taza de cerámica gigante, rodeado de una "espuma" esponjosa hecha de mini nubes, simulando un relajante baño de burbujas térmico en pleno Polo Norte.' || char(10) || char(10) || 'Para esta manualidad necesitarás una taza de café grande, una bolsa de mini malvaviscos (nubes) y, opcionalmente, un trozo de tela azul para simular el agua bajo las nubes. Coloca al elfo con los brazos apoyados en el borde para mayor realismo. Tiempo estimado de creación: 5 minutos.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(134, 'Misión Imposible: Rayos Láser', 'El elfo se ha convertido en un agente secreto de alto riesgo. Ha sido interceptado en el pasillo intentando cruzar un sistema de seguridad infrarrojo compuesto por hilos rojos que se cruzan en todas direcciones. Su pose es acrobática, suspendido en el aire para evitar tocar el suelo.' || char(10) || char(10) || 'Materiales necesarios: Lana roja o hilo grueso de color llamativo, cinta adhesiva para fijar los hilos a las paredes del pasillo y un poco de hilo de pescar para colgar al elfo del techo de forma invisible. Tiempo estimado de creación: 20 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(110, 'El Iglú de Ingeniería Ártica', 'Nuestro pequeño arquitecto ha pasado la noche construyendo un refugio resistente al frío. Se trata de un iglú perfectamente estructurado bloque a bloque, donde el elfo asoma la cabeza por la puerta principal, listo para protegerse de cualquier ventisca navideña en la cocina.' || char(10) || char(10) || 'Necesitarás una bolsa grande de malvaviscos blancos de tamaño normal y una pistola de silicona fría o glaseado denso para unir las piezas. Usa un tazón de base para darle la forma circular inicial y luego retíralo. Tiempo estimado de creación: 45 minutos.', 'elf_snow', '[{"label":"SNOW"},{"label":"KITCHEN"},{"label":"HARD"}]', 0),
(135, 'Pesca Milagrosa en el Lavabo', 'El instinto de supervivencia ha llevado al elfo a las orillas del lavabo principal. Con una caña de pescar artesanal, intenta capturar unos peces dorados que nadan en las profundidades de la cerámica, mientras descansa cómodamente sentado sobre un rollo de papel higiénico.' || char(10) || char(10) || 'Materiales: Un palito de brocheta, hilo dental para el sedal y galletas con forma de pez o recortes de cartulina naranja. Puedes usar papel de seda azul en el fondo del lavabo para simular el agua sin usar líquido real. Tiempo estimado de creación: 10 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(76, 'Campamento Bajo las Estrellas', 'El elfo ha montado su propia zona de acampada en el dormitorio. Ha fabricado una tienda de campaña de estilo "tepee" y ha encendido una fogata acogedora donde se está calentando las manos mientras espera que amanezca para seguir con sus vigilancias.' || char(10) || char(10) || 'Necesitarás un pañuelo grande o trozo de fieltro, tres lápices para la estructura de la tienda, y unos palitos de canela para la hoguera. Usa una vela de té LED (sin llama real) para darle ese brillo cálido de noche de campo. Tiempo estimado de creación: 15 minutos.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"FOREST"},{"label":"MEDIUM"}]', 0),
(62, 'Búsqueda del Tesoro de Oro', '¡Ha aparecido un cofre misterioso! El elfo ha encontrado un escondite secreto lleno de monedas de oro y ahora las está custodiando con recelo. Ha dejado un rastro de pistas brillantes por toda la habitación para que los niños encuentren el camino hacia el botín.' || char(10) || char(10) || 'Materiales: Una cajita de madera o cartón decorada, monedas de chocolate envueltas en papel dorado y un poco de purpurina para el rastro. No olvides escribir un pequeño mapa con papel envejecido con café. Tiempo estimado de creación: 20 minutos.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(131, 'Desfile de Moda: La Momia', 'Las travesuras en el vestidor han ido demasiado lejos. El elfo intentó probarse todos los calcetines de la casa pero acabó enredándose accidentalmente en un rollo de vendas, transformándose en una pequeña y simpática momia navideña que apenas puede caminar.' || char(10) || char(10) || 'Solo necesitas un rollo de gasa médica o papel higiénico. Envuelve al elfo de forma caótica dejando que algunos hilos cuelguen por el suelo del armario o el cajón de la ropa. Tiempo estimado de creación: 5 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"DANGER"},{"label":"EASY"}]', 0),
(40, 'Cine de Juguetes Navideño', 'Es noche de estreno en el salón. El elfo ha organizado una función de cine para todos los peluches de la casa. Están sentados en filas perfectas frente a una "pantalla" (una tablet o móvil) con un enorme cubo de palomitas recién hechas para compartir.' || char(10) || char(10) || 'Materiales: Un bol pequeño con palomitas de maíz reales, tus figuras de acción favoritas y un dispositivo para reproducir una película corta. Esparce algunas palomitas por el suelo para darle ese toque de realismo de sala de cine. Tiempo estimado de creación: 10 minutos.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"FESTIVAL"},{"label":"EASY"}]', 0),
(41, 'El Robo del Tarro de Dulces', 'El elfo ha sido pillado "in fraganti" intentando escalar el tarro de cristal de las golosinas. Se encuentra colgado de la tapa con una mano, mientras con la otra intenta alcanzar un bastón de caramelo especialmente grande que brilla en el interior.' || char(10) || char(10) || 'Necesitarás un tarro de cristal transparente lleno de caramelos coloridos y un poco de masilla adhesiva o celo de doble cara para fijar la mano del elfo al borde del tarro, simulando que se está resbalando. Tiempo estimado de creación: 5 minutos.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"TREASURE"},{"label":"EASY"}]', 0),
(39, 'Carrera de Trineos de Escalera', 'La barandilla de la escalera se ha convertido en una pista de bobsleigh olímpica. El elfo se ha fabricado un trineo de alta velocidad con bastones de caramelo y está descendiendo a toda prisa, con su bufanda volando hacia atrás por la inercia del movimiento.' || char(10) || char(10) || 'Materiales: Dos bastones de caramelo reales para los patines, una cajita de cerillas vacía para el asiento del trineo y un trozo de lana roja para la bufanda. Sujeta el conjunto a la barandilla con cinta adhesiva transparente. Tiempo estimado de creación: 15 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"FESTIVAL"},{"label":"MEDIUM"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (66, 'El Banquete Real de Mini-Tortitas', '¡El elfo se ha despertado con un hambre voraz y ha decidido montar un desayuno de lujo directamente sobre la mesita de noche! Ha preparado una torre de tortitas minúsculas del tamaño de una moneda, decoradas con un chorrito de sirope y una pizca de azúcar glass, mientras espera pacientemente a que los niños despierten para compartir su festín.' || char(10) || char(10) || 'Para esta manualidad necesitarás masa de tortitas real (solo una gota por unidad), un tapón de botella que sirva como plato miniatura y un trozo de papel para simular una servilleta de tela. Es una escena encantadora para el dormitorio. Tiempo estimado de creación: 15 minutos.', 'elf_food', '[{"label":"FOOD"},{"label":"BEDROOM"},{"label":"EASY"}]', 0),
(86, 'Pesca de Altura en el Gran Lavabo', 'Nuestro aventurero ha encontrado el "lago de porcelana" en el baño y no ha podido resistir la tentación de ir de pesca. Sentado en el borde del lavabo con una caña de pescar improvisada, el elfo intenta capturar unos peces de colores que parecen haber aparecido mágicamente durante la noche en el agua cristalina.' || char(10) || char(10) || 'Necesitarás un palito de brocheta, hilo dental para el sedal y unas cuantas galletas con forma de pez (tipo Goldfish) o recortes de cartulina. Puedes añadir un poco de colorante azul al agua para un efecto más realista. Tiempo estimado de creación: 10 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(1, 'Ángel de Nieve en la Ventisca de Harina', 'El elfo extraña tanto el Polo Norte que ha decidido recrear una tormenta de nieve en plena encimera de la cocina. Ha esparcido una capa uniforme de "nieve" blanca y se ha tumbado para crear un ángel perfecto, dejando sus huellas por todo el mostrador como prueba de su diversión nocturna.' || char(10) || char(10) || 'Materiales necesarios: Harina de trigo o azúcar glass, una bandeja para contener el desorden y un tamizador para esparcir el polvo de forma homogénea. Simplemente mueve los brazos del elfo de lado a lado sobre la harina. Tiempo estimado de creación: 10 minutos.', 'elf_snow', '[{"label":"SNOW"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(142, 'El Prisionero de la Batidora', '¡Oh no! La curiosidad casi mata al elfo. Se ha quedado atrapado dentro de la batidora de vaso mientras intentaba investigar cómo se hacían los batidos navideños. Se le ve pegado al cristal con un cartel de "¡Socorro!" escrito a mano, rodeado de confeti y serpentinas que intentó usar para decorar el interior.' || char(10) || char(10) || 'Para esta escena solo necesitas la batidora (desenchufada por seguridad), un poco de confeti de colores y un trozo de papel pequeño para el cartel. Asegúrate de que el elfo esté bien visible a través del cristal. Tiempo estimado de creación: 5 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(96, 'El Enigma del Mapa del Tesoro', 'Un misterio ha llegado al salón. El elfo sostiene un pergamino envejecido que muestra un plano detallado de la planta baja con una gran "X" roja marcada detrás de las cortinas. Ha dejado una lupa de juguete al lado para que los niños le ayuden a descifrar las pistas que llevan a un botín escondido.' || char(10) || char(10) || 'Necesitarás una hoja de papel blanco, una bolsa de té húmeda para envejecer el papel, un mechero para quemar ligeramente los bordes y monedas de chocolate envueltas en oro para el tesoro final. Tiempo estimado de creación: 20 minutos.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"MYSTERY"},{"label":"LIVINGROOM"}]', 0),
(33, 'Desfile de Calcetines Navideños', '¡El elfo se ha vuelto loco con la decoración! Ha decidido que los adornos del árbol de Navidad no eran suficientes y ha colgado todos los calcetines de colores de los niños por las ramas. Se le encuentra en la cima del árbol, con un calcetín puesto a modo de saco, repartiendo alegría (y algo de desorden) textil.' || char(10) || char(10) || 'Materiales: Varios pares de calcetines de colores, pinzas de la ropa pequeñas o clips para sujetarlos a las ramas del árbol y, por supuesto, el propio árbol de Navidad. Tiempo estimado de creación: 15 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"FESTIVAL"},{"label":"MEDIUM"}]', 0),
(132, 'Tirolina Extrema de Salón', 'Para el elfo, el salón es un parque de atracciones. Ha montado una tirolina que cruza de una estantería al árbol de Navidad utilizando un bastón de caramelo como polea. Está congelado en el tiempo justo en mitad del descenso, con su bufanda volando (gracias a un alambre oculto).' || char(10) || char(10) || 'Necesitarás cordel resistente o hilo de pescar, un bastón de caramelo real y cinta adhesiva fuerte para los anclajes. Es fundamental tensar bien la cuerda para que el elfo no se deslice hacia abajo. Tiempo estimado de creación: 30 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"LIVINGROOM"},{"label":"HARD"}]', 0),
(19, 'Escondite en la Montaña de Colada', 'Después de una noche agotadora, el elfo ha encontrado el lugar más suave y cálido de la casa: el cesto de la ropa recién salida de la secadora. Se ha enterrado entre toallas y camisetas blancas, dejando solo su gorro rojo asomando como si fuera un volcán en una cordillera de algodón.' || char(10) || char(10) || 'Solo necesitas un cesto de ropa y varias prendas blancas o suaves. Coloca al elfo en el fondo y ve añadiendo ropa encima con cuidado hasta que solo se vea la punta de su sombrero. Tiempo estimado de creación: 5 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"BEDROOM"},{"label":"EASY"}]', 0),
(84, 'El Código Secreto de la Caja Fuerte', 'Un gran misterio rodea al elfo esta mañana. Está sentado frente a una caja cerrada con un candado de juguete y sostiene una serie de acertijos matemáticos que los niños deben resolver para obtener la combinación. Dentro de la caja, el brillo del "tesoro" se intuye por las rendijas.' || char(10) || char(10) || 'Materiales: Una caja pequeña (puede ser de zapatos), un candado o cinta adhesiva simulándolo, papel y rotuladores para las pistas. Puedes esconder dulces o un juguete pequeño dentro. Tiempo estimado de creación: 40 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"TREASURE"},{"label":"HARD"}]', 0),
(31, 'Atrapado en la Cascada de Burbujas', 'Una travesura en el baño que se fue de las manos. El elfo intentó darse un baño de burbujas pero usó demasiado jabón y ahora una "cascada" de espuma (algodón) desborda del lavabo hasta el suelo. El elfo está nadando entre la espuma con unas gafas de buceo hechas de cartulina.' || char(10) || char(10) || 'Necesitarás una bolsa grande de bolas de algodón o nubes de azúcar blancas, jabón de manos para el aroma y cartulina para las gafas de buceo. Pega el algodón con cinta de doble cara para crear el efecto de desbordamiento. Tiempo estimado de creación: 25 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"DANGER"},{"label":"HARD"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (120, 'Vuelo en Globo de Chuches', '¡El elfo ha decidido surcar los cielos del salón! Ha construido un globo aeroestático improvisado usando un globo inflado y una cesta de mimbre pequeña. Se encuentra suspendido cerca de una lámpara, saludando desde las alturas mientras "observa" quién se porta bien desde una perspectiva privilegiada.' || char(10) || char(10) || 'Para esta manualidad necesitarás un globo de helio (o uno normal pegado al techo con celo), una cesta pequeña o un vaso de papel decorado, y cuatro hilos de lana para unir el globo a la barquilla. Coloca algunos caramelos dentro para que parezca que lleva provisiones. Tiempo estimado de creación: 15 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"LIVINGROOM"},{"label":"MEDIUM"}]', 0),
(133, 'Spa de Nubes Tostadas', 'Después de tanto viaje, el elfo se está dando un capricho en la cocina. Ha montado un pequeño campamento de lujo donde está "tostando" malvaviscos sobre una vela electrónica. Está sentado en una esponja de cocina, envuelto en una servilleta a modo de albornoz, disfrutando de un momento de paz antes del caos matutino.' || char(10) || char(10) || 'Materiales necesarios: Una vela LED de té (importante: sin fuego real), palillos de dientes, mini malvaviscos y una servilleta blanca. Puedes usar un posavasos como alfombra para delimitar su zona de relax. Tiempo estimado de creación: 10 minutos.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(73, 'Barba de Nieve en el Espejo', '¡Travesura en el baño! El elfo se ha levantado con ganas de un cambio de look y ha intentado afeitarse frente al espejo principal. Se ha cubierto la cara con espuma de afeitar (o nata montada) y ha dejado un mensaje gracioso escrito en el cristal, rodeado de huellas blancas por todo el lavabo.' || char(10) || char(10) || 'Necesitarás espuma de afeitar, un palito de helado que haga de cuchilla y un rotulador de tiza líquida para escribir en el espejo. Asegúrate de poner solo un poco de espuma en la cara del elfo para no estropear el fieltro. Tiempo estimado de creación: 5 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"EASY"}]', 0),
(124, 'El Laberinto de Lana', 'Un misterio ha bloqueado la entrada al dormitorio de los niños. El elfo ha pasado la noche tejiendo una red gigante de lana que cruza el marco de la puerta de lado a lado, como si fuera una tela de araña láser. Él está en el centro, sosteniendo el ovillo y desafiando a todos a pasar sin tocar los hilos.' || char(10) || char(10) || 'Para este montaje necesitarás un ovillo de lana (el rojo queda muy bien como "láser") y cinta adhesiva que no dañe el marco de la puerta. Cruza los hilos en diferentes ángulos y alturas para crear un verdadero reto físico. Tiempo estimado de creación: 20 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"BEDROOM"},{"label":"HARD"}]', 0),
(129, 'La Búsqueda del Tesoro Congelado', '¡El elfo ha traído un trozo del Polo Norte! Ha escondido varias monedas de chocolate dentro de un bloque de hielo que ha dejado en el fregadero. Junto a él, hay una pequeña nota con instrucciones sobre cómo los niños deben usar "herramientas" (agua templada y sal) para rescatar el botín atrapado.' || char(10) || char(10) || 'Materiales: Un recipiente con agua congelada previamente con monedas o juguetes dentro, y una bandeja para evitar derrames. Es una actividad sensorial increíble que mantendrá a los niños entretenidos un buen rato. Tiempo estimado de creación: 10 minutos (más el tiempo de congelación).', 'elf_treasure', '[{"label":"TREASURE"},{"label":"SNOW"},{"label":"MEDIUM"}]', 0),
(137, 'Patinaje sobre Cristal', 'El elfo ha convertido la mesa del comedor en una pista de patinaje sobre hielo olímpica. Usando un espejo o papel de aluminio estirado, se encuentra haciendo piruetas sobre sus patines hechos de clips, rodeado de otros juguetes que hacen de público entusiasmado por su actuación.' || char(10) || char(10) || 'Necesitarás papel de aluminio o un espejo plano, dos clips metálicos para los pies del elfo y un poco de bicarbonato de sodio para simular la nieve acumulada en los bordes de la pista. Tiempo estimado de creación: 10 minutos.', 'elf_snow', '[{"label":"SNOW"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(4, 'Cuidado con la Tostadora', '¡Situación de peligro en la cocina! El elfo ha intentado ver cómo funciona la tostadora y se ha quedado medio asomado por una de las ranuras. Parece que buscaba el calor del hogar, pero ha terminado rodeado de migas de pan y con cara de no saber muy bien cómo salir de ese laberinto de metal.' || char(10) || char(10) || 'Solo necesitas una tostadora (¡desenchufada siempre!) y un par de rebanadas de pan tostado real para decorar la escena. Coloca al elfo de modo que solo asome la mitad superior del cuerpo. Tiempo estimado de creación: 5 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(54, 'El Desfile de Moda del Armario', 'El elfo ha decidido que su traje rojo es demasiado aburrido y ha asaltado el cajón de los calcetines. Se ha fabricado un "vestido de alta costura" uniendo varios calcetines desparejados con pinzas de la ropa y está desfilando sobre una pasarela hecha de zapatos alineados.' || char(10) || char(10) || 'Busca 4 o 5 calcetines de colores brillantes, pinzas de la ropa pequeñas y los zapatos más divertidos de la familia para crear la pasarela. Es una escena muy colorida y simpática para el dormitorio. Tiempo estimado de creación: 15 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"BEDROOM"},{"label":"MEDIUM"}]', 0),
(128, 'El Árbol de Construcción Galáctica', '¡Trabajo en equipo! El elfo ha traído sus piezas de construcción favoritas y está ayudando a montar un árbol de Navidad alternativo hecho completamente de bloques. Se le ve con un casco de obra (hecho de papel) dirigiendo a otras figuras de acción en esta gran obra de ingeniería.' || char(10) || char(10) || 'Materiales: Bloques de construcción tipo LEGO o similares, cartulina amarilla para el casco y un plano dibujado a mano sobre un trozo de papel. Puedes construir una estructura simple y dejar que el elfo sostenga la última pieza. Tiempo estimado de creación: 25 minutos.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"ADVENTURE"},{"label":"HARD"}]', 0),
(93, 'Poción Mágica en el Lavabo', 'Un experimento alquímico ha tenido lugar en el cuarto de baño. El elfo ha mezclado "polvos de estrellas" en el agua del lavabo y la ha vuelto de un color verde fluorescente. Está sosteniendo un cepillo de dientes como si fuera una varita mágica, sorprendido por el resultado de su propio hechizo.' || char(10) || char(10) || 'Para este efecto necesitarás colorante alimentario (solo unas gotas en el agua del lavabo taponado) y un poco de purpurina biodegradable. Es una sorpresa visual muy potente cuando los niños entran a lavarse los dientes. Tiempo estimado de creación: 5 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"BATHROOM"},{"label":"MEDIUM"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (61, 'Jacuzzi de Chocolate Caliente', 'Después de una noche gélida vigilando la casa, el elfo ha decidido entrar en calor con un baño de lujo. Ha llenado una de las tazas favoritas de la familia con cacao en polvo y ha creado un jacuzzi de chocolate donde descansa plácidamente, rodeado de una densa capa de mini nubes que actúan como burbujas relajantes.' || char(10) || char(10) || 'Para esta escena necesitarás una taza de café, chocolate en polvo (solo para la superficie si no quieres gastar mucho), mini malvaviscos y una pajita de papel decorativa. Coloca al elfo con los brazos hacia fuera para que parezca que disfruta del vapor. Tiempo estimado de creación: 5 minutos.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(68, 'El Camino del Arcoíris de Cereales', '¡La cocina se ha vuelto mágica! El elfo ha decidido que el camino hacia el desayuno debe ser especial y ha creado un sendero multicolor que atraviesa toda la encimera. Al final del arcoíris, el elfo espera sentado sobre una montaña de cereales, asegurándose de que nadie se quede sin su dosis de energía matutina.' || char(10) || char(10) || 'Materiales necesarios: Una caja de cereales redondos de colores (tipo Froot Loops), un par de nubes blancas para simular las nubes al principio y final del camino, y un poco de algodón. Ordena los cereales por colores para crear el efecto degradado. Tiempo estimado de creación: 15 minutos.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(43, 'Pizzería Artesanal del Elfo', '¡Hoy no se cocina, el elfo se encarga! Ha montado su propio puesto de pizzas minúsculas sobre la mesa. Con un delantal improvisado y las manos manchadas de "harina", el elfo presenta sus creaciones artesanales del tamaño de un bocado, listas para ser devoradas por cualquier juguete hambriento que pase por allí.' || char(10) || char(10) || 'Necesitarás galletas saladas redondas para la base, un poco de mermelada roja o ketchup para la salsa, y queso rallado real o coco seco. Como toque final, usa un trozo de caja de cartón pequeña para simular el embalaje de la pizza. Tiempo estimado de creación: 20 minutos.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(147, 'Buceo en el Mar de Gelatina', 'El elfo ha encontrado un océano azul y dulce en la nevera. Equipado con un visor de buceo, se ha sumergido en un cuenco de gelatina donde intenta atrapar unos peces de gominola que han quedado atrapados en la profundidad. Es una escena visualmente impactante y muy refrescante para los niños.' || char(10) || char(10) || 'Materiales: Un paquete de gelatina azul preparado el día anterior, pececitos de gominola introducidos antes de que cuaje y una pajita cortada para simular el tubo de buceo. Recuerda limpiar bien al elfo después de esta aventura para que no se quede pegajoso. Tiempo estimado de creación: 10 minutos (más preparación de la gelatina).', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"HARD"}]', 0),
(138, 'Cárcel de Bastones de Caramelo', '¡Atrapado por su glotonería! El elfo intentó llevarse todos los bastones de caramelo del árbol y ha terminado encerrado en una prisión de azúcar. Los bastones forman los barrotes de su celda y tiene un cartel que dice "Perdón por ser tan dulce", mientras mira con arrepentimiento a través de las rayas rojas y blancas.' || char(10) || char(10) || 'Necesitarás entre 8 y 10 bastones de caramelo reales y un poco de cinta adhesiva o cordel para unirlos en la parte superior e inferior formando una jaula. Coloca al elfo dentro antes de cerrar la estructura. Tiempo estimado de creación: 15 minutos.', 'elf_food', '[{"label":"FOOD"},{"label":"DANGER"},{"label":"EASY"}]', 0),
(111, 'La Pastelería de Mini Donas', 'El elfo ha decidido que las donas normales son demasiado grandes para él, así que ha horneado su propia tanda de "mini donas" navideñas. Las tiene expuestas en un plato pequeño, decoradas con glaseado y chispitas de colores, invitando a todos a probar estas delicias del tamaño de una uña.' || char(10) || char(10) || 'Para esta manualidad usa cereales redondos con agujero (tipo Cheerios o Anisados), sumérgelos en chocolate derretido o glaseado de azúcar y añade virutas de colores mientras estén húmedos. Es un detalle comestible que encanta a los más pequeños. Tiempo estimado de creación: 15 minutos.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(119, 'Aventura en la Selva de Brócoli', 'Incluso los elfos saben que hay que comer verdura, ¡aunque sea para jugar! El elfo se ha perdido en un bosque de árboles gigantes verdes (ramilletes de brócoli) y está intentando encontrar el camino de salida. Ha montado un picnic saludable en un claro del bosque usando una rodaja de zanahoria como mesa.' || char(10) || char(10) || 'Materiales: 3 o 4 piezas grandes de brócoli crudo, una rodaja de zanahoria y un poco de hummus o salsa ranchera para simular un "charco" de barro. Es una forma divertida de presentar vegetales a los niños. Tiempo estimado de creación: 10 minutos.', 'elf_food', '[{"label":"FOOD"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(87, 'Piscina de Virutas Mágicas', '¡Se acabó el frío, es hora de nadar! El elfo ha convertido un bol de cristal en una piscina de bolas, pero en lugar de plástico, ha usado miles de virutas de colores dulces. Está tumbado boca arriba con unas gafas de sol hechas de papel, disfrutando de un "baño" extremadamente azucarado y colorido.' || char(10) || char(10) || 'Necesitarás un cuenco pequeño y un par de botes de virutas (sprinkles) de colores para tartas. Si no tienes suficientes virutas, puedes rellenar el fondo con arroz y poner las virutas solo en la capa superior. Tiempo estimado de creación: 5 minutos.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(117, 'La Fortaleza de Azúcar', 'El elfo ha construido una defensa impenetrable en la cocina. Usando bloques de ingeniería comestibles (terrones de azúcar), ha levantado una muralla fortificada desde donde vigila que nadie robe los dulces de Navidad antes de tiempo. Es una obra de arquitectura dulce que desafía la gravedad.' || char(10) || char(10) || 'Materiales: Una caja de terrones de azúcar y un poco de miel o leche condensada para usar como pegamento entre los bloques. Puedes añadir pequeñas banderas hechas con palillos y papel. Tiempo estimado de creación: 30 minutos.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"HARD"}]', 0),
(67, 'El Barista de Batidos', '¡Marchando un batido especial! El elfo ha tomado el control de la batidora y ha preparado una bebida mágica. Está sosteniendo una pajita gigante que se introduce en un vaso de leche con chocolate, con una montaña de nata montada que le llega hasta el gorro y virutas de chocolate por todas partes.' || char(10) || char(10) || 'Prepara un vaso de leche con cacao, añade nata montada real (o algodón si prefieres que dure todo el día) y coloca al elfo sujetando una pajita dentro del vaso. Ten cuidado de no manchar demasiado el traje del elfo. Tiempo estimado de creación: 10 minutos.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (82, 'La Pasarela de Alta Costura', '¡El pasillo se ha convertido en la Fashion Week! El elfo ha desplegado una bufanda larga a modo de alfombra roja y ha desfilado con un "traje" hecho con un envoltorio de bombón brillante. Está rodeado de otros peluches que hacen de fotógrafos con cámaras de juguete, capturando su mejor ángulo.' || char(10) || char(10) || 'Para esta manualidad necesitarás una bufanda colorida, un poco de papel de aluminio o envoltorios de dulces para su ropa, y otros juguetes de la casa. Coloca al elfo en una pose de modelo profesional. Tiempo estimado de creación: 15 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"FESTIVAL"},{"label":"MEDIUM"}]', 0),
(102, 'Atrapado en el Calcetín Perdido', 'Parece que el elfo intentó buscar ese calcetín que siempre desaparece en la lavadora y ha terminado metido en un lío. Solo se le ven las piernas asomando por la parte superior de un calcetín desparejado, mientras el resto de su cuerpo está totalmente oculto en las profundidades del tejido.' || char(10) || char(10) || 'Materiales: Un calcetín de adulto (preferiblemente con motivos navideños) y un poco de relleno o papel en el fondo para que el calcetín mantenga la forma mientras el elfo está dentro boca abajo. Tiempo estimado de creación: 5 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"DANGER"},{"label":"EASY"}]', 0),
(92, 'El Columpio de Percha', '¡Adrenalina en el armario! El elfo ha encontrado una percha libre y la ha convertido en un columpio trapecista. Está colgado de la barra del armario o de un pomo de una puerta, balanceándose con alegría mientras observa toda la ropa desde una perspectiva muy divertida.' || char(10) || char(10) || 'Necesitarás una percha de ropa normal y un poco de hilo de pescar o cordel para asegurar las manos del elfo a la barra inferior de la percha. Asegúrate de que quede bien equilibrado para que no se caiga. Tiempo estimado de creación: 10 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(17, 'Expedición al Monte Zapato', 'Para un elfo, un montón de zapatos es una cordillera esperando ser explorada. Se encuentra en la cima del zapato más alto de la casa, equipado con una "mochila" (un tapón de botella con tiras de hilo) y una bandera de victoria que ha clavado en la lengüeta del calzado.' || char(10) || char(10) || 'Materiales: Varios zapatos y botas de la familia apilados artísticamente, un palillo de dientes y un trozo de papel para la bandera. Es una escena ideal para dejar en el recibidor o la entrada. Tiempo estimado de creación: 10 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(105, 'Saco de Dormir de Guante', 'Incluso los ayudantes de Santa necesitan una siesta acogedora. El elfo ha encontrado un guante de lana y se ha metido dentro como si fuera un saco de dormir térmico. Solo asoma su carita y su gorro rojo, descansando plácidamente sobre un cojín del sofá o en la mesita de noche.' || char(10) || char(10) || 'Solo necesitas un guante o una manopla de invierno. Puedes doblar el borde del guante hacia fuera para que parezca una cama de verdad y colocar un pañuelo pequeño a modo de almohada. Tiempo estimado de creación: 5 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"BEDROOM"},{"label":"EASY"}]', 0),
(89, 'El Túnel del Pantalón', '¡Misión de exploración subterránea! El elfo ha decidido que las perneras de unos vaqueros son túneles secretos que conectan las habitaciones. Se le puede ver asomando la cabeza por el tobillo de un pantalón que se ha quedado "olvidado" sobre la cama, con una linterna en la mano.' || char(10) || char(10) || 'Materiales: Unos pantalones vaqueros o de chándal y una linterna pequeña (puede ser de juguete o una luz LED). Coloca los pantalones con un poco de volumen para que parezca que hay alguien moviéndose dentro. Tiempo estimado de creación: 8 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"MYSTERY"},{"label":"EASY"}]', 0),
(50, 'Encantador de Corbatas', 'En un rincón del salón, el elfo se ha convertido en un encantador de serpientes, pero en lugar de cobras, está usando las corbatas de papá. Sentado con las piernas cruzadas y una flauta (un lápiz), ha logrado que las corbatas "bailen" y se mantengan erguidas frente a él.' || char(10) || char(10) || 'Necesitarás 2 o 3 corbatas y un poco de alambre fino por dentro de las mismas para que mantengan la forma vertical. Usa un lápiz o un palito como flauta para el elfo. Tiempo estimado de creación: 20 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"LIVINGROOM"},{"label":"MEDIUM"}]', 0),
(146, 'Escondite en el Gorro de Lana', '¡Cuidado al ponerte el gorro hoy! El elfo se ha camuflado perfectamente dentro de un gorro de lana con pompón. Ha dado la vuelta al gorro y lo ha convertido en un nido circular donde se ha hecho un ovillo, casi imposible de detectar a primera vista si no te fijas en su gorrito rojo.' || char(10) || char(10) || 'Solo necesitas un gorro de lana de invierno. Dale la vuelta o hazle un hueco en el centro y coloca al elfo de forma que quede bien resguardado y calentito. Tiempo estimado de creación: 5 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"BEDROOM"},{"label":"EASY"}]', 0),
(99, 'El Duende de Lavandería', 'Nuestro amigo ha decidido que es un buen día para hacer la colada, pero se ha pasado con el detergente. Está sentado encima de la lavadora rodeado de una montaña de "espuma" blanca (bolas de algodón) y sostiene un calcetín diminuto que parece haber encogido en el lavado.' || char(10) || char(10) || 'Materiales: Bolas de algodón, un bote de detergente vacío y un calcetín de bebé o una prenda muy pequeña. Esparce el algodón para simular que la espuma se está desbordando. Tiempo estimado de creación: 12 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"BATHROOM"},{"label":"MEDIUM"}]', 0),
(65, 'Bufanda-Serpiente en el Pasillo', '¡Cuidado por dónde pisas! El elfo ha domado una bufanda de rayas y la ha colocado en forma de zigzag por el pasillo para que parezca una serpiente gigante. Él va montado sobre la "cabeza" de la serpiente, usando un cinturón a modo de riendas para dirigir a su nueva y suave mascota.' || char(10) || char(10) || 'Necesitarás una bufanda larga, un cinturón fino o un cordón de zapato para las riendas, y un par de botones o pegatinas para ponerle ojos a la bufanda. Tiempo estimado de creación: 10 minutos.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (123, 'Salto Base desde la Lámpara', '¡El elfo se ha lanzado al vacío! Aprovechando la altura de la lámpara del salón, ha improvisado un paracaídas circular y está descendiendo lentamente hacia el sofá. Es una maniobra arriesgada que solo un elfo entrenado en el Polo Norte podría ejecutar con tanta elegancia.' || char(10) || char(10) || 'Materiales: Una servilleta de papel grande o un filtro de café, cuatro hilos de lana y cinta adhesiva para unir los hilos a la espalda del elfo. Cuélgalo del techo o la lámpara con un hilo de pescar invisible para que parezca que está flotando en el aire. Tiempo estimado de creación: 15 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"LIVINGROOM"},{"label":"MEDIUM"}]', 0),
(97, 'Rápel por la Nevera Ártica', 'La conquista de la cocina ha comenzado. El elfo ha sido avistado descendiendo por la puerta de la nevera mediante una cuerda de seguridad profesional. Su objetivo parece ser el cajón de los embutidos, y no se detendrá ante nada hasta completar su misión de descenso vertical.' || char(10) || char(10) || 'Necesitarás un cordel largo o hilo dental y un clip de oficina que sirva como mosquetón de escalada. Fija un extremo de la cuerda a la parte superior de la nevera con un imán o cinta, y enrolla el otro extremo en el cuerpo del elfo en una pose de descenso. Tiempo estimado de creación: 10 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(77, 'Safari entre Dinosaurios', '¡Supervivencia en la era jurásica! El elfo ha viajado en el tiempo y ha sido capturado cabalgando sobre el lomo de un temible T-Rex. Armado con un lazo de cuerda, está intentando domar a las bestias prehistóricas del cuarto de juegos en una expedición de safari sin precedentes.' || char(10) || char(10) || 'Materiales: Figuras de dinosaurios de juguete o animales de plástico grandes y un trozo de cordel para simular las riendas. Coloca al elfo sentado firmemente sobre el juguete más grande que encuentres para darle escala a la aventura. Tiempo estimado de creación: 10 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(37, 'Rafting en los Rápidos del Baño', 'El elfo ha construido una balsa de salvamento y se está enfrentando a las embravecidas aguas del lavabo. Con un remo en la mano y una actitud desafiante, navega entre burbujas de jabón buscando la orilla de la encimera en esta peligrosa travesía fluvial.' || char(10) || char(10) || 'Necesitarás un par de esponjas de cocina unidas o unos palitos de helado para formar la balsa, y un bastoncillo de los oídos como remo. Puedes añadir un poco de papel de seda azul alrededor para simular las olas del río. Tiempo estimado de creación: 15 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"BATHROOM"},{"label":"MEDIUM"}]', 0),
(116, 'Exploración de la Cueva de Cojines', 'En las profundidades del sofá existe un mundo desconocido. El elfo se ha equipado con una linterna frontal y se ha adentrado en una oscura gruta formada por los cojines. Su misión es recuperar el "mando a distancia perdido", una reliquia antigua que los humanos buscan desesperadamente.' || char(10) || char(10) || 'Materiales: Los cojines del sofá dispuestos en forma de túnel y una luz LED pequeña o una linterna de juguete. Coloca al elfo asomando la cabeza desde la oscuridad del túnel para generar misterio. Tiempo estimado de creación: 10 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(5, 'Vuelo Acrobático en Avión de Papel', '¡Cuidado con el tráfico aéreo! El elfo ha diseñado un prototipo de avión de papel de alta velocidad y está sobrevolando el pasillo. Parece que ha perdido el control y está a punto de realizar un aterrizaje forzoso sobre la planta del recibidor.' || char(10) || char(10) || 'Solo necesitas una hoja de papel para hacer el avión (puedes buscar un diseño complejo tipo "stunt") y un poco de cinta para asegurar al elfo en la "cabina". Cuélgalo del techo con hilo invisible para que parezca que está en pleno vuelo. Tiempo estimado de creación: 10 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(18, 'Cruce del Puente Colgante', 'El abismo entre la mesa y la silla es enorme, pero el elfo ha construido un puente de ingeniería con materiales de fortuna. Se encuentra justo en el centro del puente, manteniendo el equilibrio mientras el viento (del ventilador) amenaza con hacerlo caer al vacío del suelo de madera.' || char(10) || char(10) || 'Materiales: Dos sillas o muebles cercanos, varios lápices o reglas de plástico para los tablones y cordel para las barandillas del puente. Es una construcción que requiere algo de equilibrio y paciencia. Tiempo estimado de creación: 25 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"LIVINGROOM"},{"label":"HARD"}]', 0),
(26, 'Misión Espacial: Aterrizaje Lunar', '¡Un pequeño paso para un elfo, un gran salto para la Navidad! Nuestro aventurero ha aterrizado su nave espacial en un planeta desconocido (una calabaza o un balón de fútbol). Ha plantado su bandera y está recogiendo muestras de rocas lunares para llevarlas de vuelta al Polo Norte.' || char(10) || char(10) || 'Necesitarás papel de aluminio para envolver un objeto redondo, un palillo de dientes con un trozo de papel para la bandera y un casco improvisado con un vaso de plástico transparente pequeño. Tiempo estimado de creación: 20 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"BEDROOM"},{"label":"HARD"}]', 0),
(70, 'Carrera de Obstáculos Ninja', 'El entrenamiento para repartir regalos es duro. El elfo ha montado un circuito de entrenamiento ninja en el suelo del salón: debe saltar sobre bloques de construcción, reptar bajo hilos de lana y escalar muros de libros sin ser detectado por los radares enemigos.' || char(10) || char(10) || 'Materiales: Piezas de LEGO, hilos de colores estirados entre muebles bajos y libros apilados. Coloca al elfo en una postura de sigilo, como si estuviera a punto de saltar un obstáculo. Tiempo estimado de creación: 20 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"LIVINGROOM"},{"label":"MEDIUM"}]', 0),
(52, 'Infiltración en la Fortaleza de Regalos', 'El elfo ha sido enviado en una misión de reconocimiento para verificar el estado de los paquetes. Ha usado ventosas (celo doblado) para trepar por las cajas de cartón y está espiando por una pequeña rendija del papel de regalo para confirmar el contenido secreto.' || char(10) || char(10) || 'Necesitarás algunas cajas vacías envueltas en papel de regalo y un cúter para hacer un corte pequeño por donde asome el elfo. Es una escena que genera muchísima expectación en los niños. Tiempo estimado de creación: 15 minutos.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"TREASURE"},{"label":"MEDIUM"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (3, 'El Escritor de Postales Navideñas', 'Nuestro elfo sabe que no hay nada más bonito que una felicitación escrita a mano. Se ha pasado la noche redactando mini postales para todos los juguetes de la casa y para la familia, usando un buzón improvisado para que los niños dejen sus propias cartas a Santa.' || char(10) || char(10) || 'Necesitarás cartulina de colores cortada en rectángulos diminutos, sobres de papel hechos a mano y un bolígrafo de punta fina. Puedes usar una caja de cereales pequeña pintada de rojo como buzón oficial. Tiempo estimado de creación: 20 minutos.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(53, 'El Elfo-Adorno Resplandeciente', '¡El elfo quiere ser la estrella de la fiesta! Se ha camuflado entre las ramas del árbol de Navidad, pero no de cualquier manera: se ha envuelto en espumillón brillante y se ha colgado de una rama mediante una bola decorativa, esperando a ver cuánto tardan en encontrarlo entre tanto brillo.' || char(10) || char(10) || 'Materiales: Espumillón de colores, una bola de Navidad (quítale el gancho para que el elfo pueda "sujetarla") y el propio árbol. Asegúrate de que el elfo esté seguro para que no se caiga durante la noche. Tiempo estimado de creación: 5 minutos.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(15, 'Arquitectura en Jengibre', '¡Es hora de construir! El elfo ha tomado el mando de la construcción de la casita de jengibre. Con un casco de obrero y planos de azúcar, está supervisando que cada gominola y cada gramo de glaseado estén en su lugar para que la estructura sea resistente a los mordiscos.' || char(10) || char(10) || 'Para esta escena puedes usar un kit de casa de jengibre real o construir una versión pequeña con galletas tipo "Maria" y chocolate fundido. Esparce azúcar glass alrededor para simular la nieve de la obra. Tiempo estimado de creación: 45 minutos.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"FOOD"},{"label":"HARD"}]', 0),
(139, 'El Maestro del Papel de Regalo', 'Parece que el elfo tiene un exceso de celo con la seguridad de los regalos. Ha decidido "proteger" el mando de la televisión y los zapatos de los niños envolviéndolos meticulosamente en papel de regalo navideño, con lazos gigantes y etiquetas que ponen "¡No abrir hasta Navidad!".' || char(10) || char(10) || 'Materiales: Papel de regalo, celo y lazos. Elige un par de objetos cotidianos que los niños usen por la mañana para que la sorpresa sea más divertida al encontrarlos envueltos. Tiempo estimado de creación: 15 minutos.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(42, 'Operación Estrella Plateada', 'Colocar la estrella en lo más alto del árbol es una misión crítica. El elfo ha construido una escalera de ingeniería usando bastones de caramelo atados con lazos rojos, y está a punto de coronar el árbol con una estrella brillante que él mismo ha "fabricado" con papel de aluminio.' || char(10) || char(10) || 'Necesitarás 4 o 6 bastones de caramelo largos, hilo o cordel para atarlos como los peldaños de una escalera y papel de aluminio para la estrella. Apoya la escalera con cuidado contra el árbol. Tiempo estimado de creación: 25 minutos.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(150, 'Coro de Juguetes Navideño', '¡La música inunda el salón! El elfo ha reunido a todos los peluches y figuras de acción en una formación coral perfecta. Él está al frente, con una batuta y partituras minúsculas, dirigiendo a sus amigos en un ensayo general de villancicos clásicos.' || char(10) || char(10) || 'Materiales: Otros juguetes de la casa, un palillo de dientes como batuta y trozos de papel con notas musicales dibujadas. Puedes poner música navideña suave de fondo cuando los niños despierten. Tiempo estimado de creación: 15 minutos.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(75, 'El Elfo en la Bola de Nieve', 'Nuestro amigo se ha quedado "atrapado" en un mundo mágico de cristal. Ha entrado en un tarro de cristal que simula una bola de nieve gigante, rodeado de purpurina y pequeños pinos, creando una de las estampas más decorativas y hermosas de toda la temporada.' || char(10) || char(10) || 'Necesitarás un tarro grande de cristal, purpurina blanca o plateada, y opcionalmente un poco de algodón para el suelo. Si quieres que sea una manualidad de larga duración, no añadas agua para no estropear al elfo. Tiempo estimado de creación: 10 minutos.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"SNOW"},{"label":"MEDIUM"}]', 0),
(83, 'La Cuenta Atrás Definitiva', '¡El elfo está emocionado porque falta muy poco! Ha sido encontrado frente al calendario de Adviento, marcando con un rotulador rojo gigante los días que ya han pasado y señalando con entusiasmo el día de hoy, donde ha dejado una pequeña pista sobre la sorpresa del día.' || char(10) || char(10) || 'Solo necesitas el calendario de Adviento que ya tengas en casa y un rotulador. Si no tienes uno, puedes dibujar un calendario simple en una cartulina grande y dejar que el elfo lo "estrene". Tiempo estimado de creación: 5 minutos.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"EASY"}]', 0),
(136, 'Enredado en la Iluminación', 'Las luces de Navidad pueden ser traicioneras. El elfo intentó añadir una hilera extra de bombillas al pasillo y ha terminado completamente enredado en un cable de luces LED. Ahora brilla con diferentes colores mientras espera que alguien lo desenrede de este lío luminoso.' || char(10) || char(10) || 'Materiales: Una guirnalda de luces LED (preferiblemente a pilas para mayor seguridad). Envuelve al elfo de forma caótica pero segura, y asegúrate de que las luces no se calienten demasiado. Tiempo estimado de creación: 10 minutos.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0),
(79, 'Visitante del Portal de Belén', 'Con mucho respeto, el elfo ha ido a visitar el portal de Belén. Ha traído un pequeño regalo envuelto para colocarlo junto a los de los Reyes Magos y se ha quedado allí, charlando con los pastores y admirando la escena en un momento de paz navideña.' || char(10) || char(10) || 'Necesitarás el portal de Belén de casa y un cuadradito de papel de regalo con un lazo para el obsequio del elfo. Colócalo de forma que no desentone con las figuras tradicionales para un efecto más tierno. Tiempo estimado de creación: 5 minutos.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"MYSTERY"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (32, 'El Mensaje de Tinta Invisible', '¡Misterio absoluto! El elfo ha dejado una hoja de papel completamente en blanco sobre la mesa junto a un pincel y un pequeño cuenco con un líquido transparente. Solo los niños más astutos podrán revelar el mensaje secreto que ha enviado directamente desde el cuartel general de Santa.' || char(10) || char(10) || 'Para esta manualidad necesitarás zumo de limón o una cera blanca. Escribe el mensaje en el papel; si usas limón, los niños deberán aplicar calor (con cuidado) o acuarelas para verlo. Si usas cera blanca, bastará con pintar encima con rotuladores. Tiempo estimado de creación: 10 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"EASY"},{"label":"LIVINGROOM"}]', 0),
(103, 'Escena del Crimen: La Galleta Desaparecida', '¡Alguien ha robado la galleta de medianoche! El elfo ha acordonado una zona de la encimera con cinta de "No pasar" y ha marcado con tiza la silueta del dulce desaparecido. Hay migas sospechosas que delatan al culpable, y nuestro elfo está tomando muestras con una lupa en mano.' || char(10) || char(10) || 'Materiales: Harina o tiza para dibujar la silueta, cinta aislante de color llamativo para el cordón policial y migas de galleta real. Puedes añadir una lupa de juguete para que el elfo parezca un profesional. Tiempo estimado de creación: 15 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(22, 'El Enigma del Código César', 'El elfo ha dejado una nota cifrada llena de símbolos extraños y números. Para descubrir dónde ha escondido el desayuno de hoy, los niños deberán usar un disco decodificador que el elfo ha construido a medias, retándolos a completar la lógica del mensaje antes de que se enfríe la leche.' || char(10) || char(10) || 'Necesitarás dos círculos de cartulina de diferentes tamaños unidos por un encuadernador con el abecedario escrito. Deja una pista visual de cuál es la letra clave (por ejemplo, una "A" alineada con una "D"). Tiempo estimado de creación: 25 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"HARD"},{"label":"KITCHEN"}]', 0),
(10, 'La Huella del Intruso Gigante', '¡Una huella enorme ha aparecido en el pasillo! El elfo está analizando la marca con cara de preocupación, comparándola con el tamaño de su propio pie. Parece que un visitante misterioso (¿un Yeti? ¿Santa?) ha entrado en la casa mientras todos dormían y el elfo está siguiendo el rastro.' || char(10) || char(10) || 'Materiales: Harina o polvos talco para crear la forma de una pisada grande en el suelo. Usa una bota de adulto para presionar sobre el polvo y crear la forma perfecta. Coloca al elfo junto a la huella con una cinta métrica. Tiempo estimado de creación: 5 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"SNOW"},{"label":"EASY"}]', 0),
(35, 'El Caso de la Llave Encadenada', 'El elfo sostiene una llave antigua atada a su muñeca, pero no hay ninguna cerradura a la vista. Ha dejado una serie de fotos o dibujos de rincones de la casa que, al unirlos, revelan la ubicación del cofre misterioso que esa llave abre. ¡La búsqueda ha comenzado!' || char(10) || char(10) || 'Necesitarás una llave vieja, un cordel y una caja pequeña con un candado (o cerrada con mucha cinta). Esconde la caja en un lugar difícil y deja pistas fotográficas por el salón. Tiempo estimado de creación: 20 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"TREASURE"},{"label":"MEDIUM"}]', 0),
(144, 'La Sombra del Espía Nocturno', 'Una silueta misteriosa se proyecta en la pared del pasillo. Al encender la luz, los niños descubrirán que el elfo ha montado un teatro de sombras chinas detrás de una sábana tensada, ocultando su verdadera posición y dejando solo un perfil enigmático que parece vigilar el árbol.' || char(10) || char(10) || 'Materiales: Una linterna potente, una sábana blanca o papel cebolla y una estructura para sujetarlo. Coloca al elfo entre la luz y la tela para que su sombra se vea gigante en la pared. Tiempo estimado de creación: 15 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"MEDIUM"},{"label":"LIVINGROOM"}]', 0),
(112, 'Laboratorio de Huellas Dactilares', '¡Investigación forense en el baño! El elfo ha encontrado huellas dactilares "sospechosas" en el espejo y las ha cubierto con polvos mágicos para identificarlas. Tiene una lista de sospechosos con las huellas de todos los miembros de la familia para encontrar al responsable de gastar el jabón.' || char(10) || char(10) || 'Necesitarás cacao en polvo o polvos talco, un pincel suave y celo transparente para "levantar" las huellas del cristal. Prepara una ficha de cartulina con las huellas reales de la familia para comparar. Tiempo estimado de creación: 30 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"BATHROOM"},{"label":"HARD"}]', 0),
(48, 'El Secuestro de los Juguetes Favoritos', '¡Alerta roja! Los peluches favoritos de los niños han aparecido con los ojos vendados y las manos atadas (suavemente). El elfo está sentado en una silla de mando, con una máscara de detective, exigiendo que se resuelva un acertijo para liberar a los rehenes del juego.' || char(10) || char(10) || 'Materiales: Otros juguetes, tiras de tela para las vendas y una nota con un acertijo rimado. Asegúrate de que los nudos sean fáciles de desatar para los niños. Tiempo estimado de creación: 10 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0),
(125, 'El Puzzle del Mensaje Perdido', 'El elfo ha roto su mensaje importante en 10 trozos y los ha esparcido por toda la habitación. Los niños deberán encontrar todas las piezas y encajarlas como un puzzle para leer la advertencia urgente que el elfo ha traído desde el taller de juguetes.' || char(10) || char(10) || 'Solo necesitas una hoja de papel con un dibujo o mensaje colorido. Córtala en formas irregulares y escóndelas en lugares visibles pero estratégicos. El elfo debe sostener la pieza central. Tiempo estimado de creación: 15 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"EASY"},{"label":"BEDROOM"}]', 0),
(95, 'El Código del Espejo Empañado', 'Un mensaje fantasmagórico ha aparecido en el espejo del baño. No se ve nada a simple vista, pero cuando el ambiente se calienta, las letras empiezan a brillar. El elfo está sentado sobre el grifo, esperando a que alguien se duche para que el secreto sea revelado.' || char(10) || char(10) || 'Para este truco, escribe un mensaje en el espejo seco usando un poco de jabón de manos en el dedo o un bastoncillo. Cuando el espejo se empañe con el vapor, el mensaje quedará limpio y será legible. Tiempo estimado de creación: 5 minutos.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"BATHROOM"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (107, 'Patinaje Artístico sobre Espejo', '¡El elfo ha montado una pista de patinaje profesional en el salón! Aprovechando una superficie reflectante, ha estado practicando piruetas y ochos durante toda la noche. Se le encuentra en una pose de equilibrio perfecta, rodeado de montículos de nieve que brillan bajo las luces del árbol.' || char(10) || char(10) || 'Necesitarás un espejo de mano o de pared colocado horizontalmente, dos clips metálicos pegados a los pies del elfo como patines y una buena cantidad de bicarbonato de sodio o purpurina blanca para los bordes. Tiempo estimado de creación: 10 minutos.', 'elf_snow', '[{"label":"SNOW"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(121, 'Guerra de Bolas de Nieve Dulces', '¡Se ha desatado una batalla épica! El elfo se ha atrincherado detrás de un fuerte de cajas de cartón y está lanzando proyectiles blancos contra un grupo de peluches. El suelo está cubierto de munición y parece que nuestro amigo lleva la delantera en este enfrentamiento ártico.' || char(10) || char(10) || 'Materiales: Mini malvaviscos (nubes) esparcidos por el suelo, una caja de pañuelos vacía para el fuerte y otros juguetes para hacer de oponentes. Crea pequeñas pirámides de malvaviscos para que parezcan pilas de bolas de nieve listas para usar. Tiempo estimado de creación: 15 minutos.', 'elf_snow', '[{"label":"SNOW"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(101, 'El Iglú de Terrones de Azúcar', 'Nuestro ingeniero polar ha construido un refugio tradicional para protegerse de las corrientes de aire nocturnas. Es un iglú estructuralmente perfecto, con su cúpula y túnel de entrada, donde el elfo descansa tranquilamente asomando solo su gorro rojo por la puerta.' || char(10) || char(10) || 'Necesitarás una caja de terrones de azúcar cuadrados y un poco de glaseado real o pegamento escolar para unir las piezas. Puedes usar un tazón del revés como base para pegar los terrones alrededor y darle la forma curva. Tiempo estimado de creación: 40 minutos.', 'elf_snow', '[{"label":"SNOW"},{"label":"KITCHEN"},{"label":"HARD"}]', 0),
(113, 'Esquí Alpino en la Barandilla', '¡La barandilla de la escalera se ha convertido en una pista de esquí de alta velocidad! El elfo ha bajado a toda prisa con sus esquís de madera, dejando un rastro de nieve tras de sí y logrando un salto acrobático justo antes de llegar al suelo del pasillo.' || char(10) || char(10) || 'Materiales: Dos palitos de helado para los esquís, dos palillos de dientes para los bastones y algodón estirado a lo largo de la barandilla para simular la nieve. Sujeta al elfo con un poco de cinta de doble cara para que no se deslice de verdad. Tiempo estimado de creación: 20 minutos.', 'elf_snow', '[{"label":"SNOW"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(88, 'Un Ángel en la Ventisca de Harina', 'El elfo no ha podido resistirse a la nieve fresca. Se ha tumbado en medio de la cocina y ha movido sus brazos y piernas con entusiasmo para dejar la marca de un ángel perfecto. Está cubierto de polvo blanco de la cabeza a los pies, como si acabara de salir de una tormenta.' || char(10) || char(10) || 'Solo necesitas harina de trigo o azúcar glass esparcida sobre una bandeja oscura o la encimera. Coloca al elfo y mueve sus extremidades para marcar la silueta antes de dejarlo allí "descansando". Tiempo estimado de creación: 5 minutos.', 'elf_snow', '[{"label":"SNOW"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(100, 'El Elfo Criogenizado en el Hielo', '¡Misterio en el congelador! El elfo ha sido encontrado atrapado dentro de un bloque de hielo sólido. Parece que intentó investigar dónde se guardaban los helados y se quedó congelado en el tiempo, esperando a que el calor de la mañana lo libere de su prisión transparente.' || char(10) || char(10) || 'Necesitarás un recipiente de plástico grande con agua donde quepa el elfo (¡protégelo primero con una bolsa de plástico hermética tipo Zip!). Déjalo en el congelador toda la noche y sácalo justo antes de que los niños despierten. Tiempo estimado de creación: 5 minutos (más 8h de congelación).', 'elf_snow', '[{"label":"SNOW"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0),
(118, 'Pesca Milagrosa en el Agujero de Hielo', 'Sentado sobre una superficie blanca y fría, el elfo está practicando la pesca en el hielo. Ha hecho un agujero perfecto y ha lanzado su sedal, esperando pacientemente a que algún pez de las profundidades árticas pique el anzuelo en esta mañana invernal.' || char(10) || char(10) || 'Materiales: Un trozo de fieltro blanco o una cartulina con un agujero azul en el centro, un palito de brocheta como caña y un pececito de gominola o cartulina atado a un hilo dental. Colócalo sobre una mesa o el suelo del baño. Tiempo estimado de creación: 10 minutos.', 'elf_snow', '[{"label":"SNOW"},{"label":"BATHROOM"},{"label":"EASY"}]', 0),
(30, 'Disfraz de Muñeco de Nieve', 'El elfo ha decidido que hoy quiere ser un muñeco de nieve. Se ha envuelto en capas de algodón blanco y se ha puesto una nariz de zanahoria diminuta, mimetizándose con un grupo de amigos hechos de nieve que ha construido para que le hagan compañía en el recibidor.' || char(10) || char(10) || 'Utiliza bolas de algodón para cubrir el cuerpo del elfo, pegándolas ligeramente. Haz otros dos muñecos de nieve solo con algodón y ponles botones de verdad o trozos de cartulina negra para los ojos. Tiempo estimado de creación: 15 minutos.', 'elf_snow', '[{"label":"SNOW"},{"label":"FESTIVAL"},{"label":"MEDIUM"}]', 0),
(85, 'Descenso en Trineo de Plato de Papel', '¡A toda máquina! El elfo está bajando por una montaña de cojines blancos montado en un trineo circular. Lleva una bufanda de lana que vuela con el viento y una expresión de pura alegría mientras se desliza hacia la base de la "montaña" nevada del salón.' || char(10) || char(10) || 'Necesitarás un plato de papel pequeño doblado para que parezca un trineo de disco, cojines blancos apilados y una bufanda de tela o lana. Usa hilo de pescar para que el trineo parezca estar en el aire durante el salto. Tiempo estimado de creación: 10 minutos.', 'elf_snow', '[{"label":"SNOW"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(106, 'Expedición al Pico de la Nevera', 'La parte superior del frigorífico es el punto más alto del mapa ártico de la cocina. El elfo ha llegado a la cumbre tras una dura escalada y ha plantado una bandera de expedición, rodeado de estalactitas de hielo que cuelgan del borde como en una cueva real.' || char(10) || char(10) || 'Materiales: Papel de plata o celofán transparente arrugado para simular el hielo, un palillo de dientes con una bandera de papel y algodón para la base de la cumbre. Es una escena ideal para aprovechar la altura de la cocina. Tiempo estimado de creación: 15 minutos.', 'elf_snow', '[{"label":"SNOW"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (143, 'Cine en la Mesita de Noche', '¡Es noche de estreno! El elfo ha organizado una sesión de cine privado para los peluches favoritos de los niños. Ha usado un teléfono móvil o una tablet como pantalla gigante y ha repartido mini cubos de palomitas para que todos disfruten de una película navideña antes de dormir.' || char(10) || char(10) || 'Materiales necesarios: Un dispositivo móvil, juguetes pequeños, y tapones de botella llenos de palomitas reales o trocitos de papel blanco arrugado. Coloca al elfo en la "fila VIP" con su propio combo de comida. Tiempo estimado de creación: 10 minutos.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(91, 'Lectura de Cuentos a la Luz de la Vela', 'Nuestro elfo es un gran amante de la literatura. Se le ha encontrado sentado sobre la almohada, leyendo un cuento infantil a un grupo de figuras de acción. Para no despertar a nadie, está usando una pequeña vela de té para iluminar las páginas del libro.' || char(10) || char(10) || 'Necesitarás un libro de cuentos abierto y una vela de té LED (nunca real). Coloca al elfo con las manos sobre las páginas como si estuviera pasando la hoja. Es una escena muy tierna para colocar junto a la cabeza del niño. Tiempo estimado de creación: 5 minutos.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"FESTIVAL"},{"label":"EASY"}]', 0),
(25, 'El Taller de Costura de Calcetines', '¡Travesura textil! El elfo ha decidido que los calcetines del niño necesitaban un toque navideño. Ha sacado un kit de costura y está intentando coser cascabeles y lazos rojos a los calcetines escolares, rodeado de hilos de colores que se han enredado por toda la colcha.' || char(10) || char(10) || 'Materiales: Un par de calcetines, hilo, aguja (de juguete o con punta roma por seguridad) y algunos cascabeles o cintas. Esparce el hilo por la cama para simular el caos creativo del elfo. Tiempo estimado de creación: 15 min.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"CLOTHES"},{"label":"MEDIUM"}]', 0),
(74, 'Acampada de Interior en el Edredón', 'El edredón de la cama se ha convertido en una cordillera de montañas blancas. El elfo ha montado su propia tienda de campaña con un pañuelo y está asomado con una linterna, vigilando que no aparezca ningún "monstruo debajo de la cama" mientras los niños duermen.' || char(10) || char(10) || 'Necesitarás un pañuelo de cuello, dos lápices para hacer los postes de la tienda y una linterna pequeña. Colócalo sobre la manta o la colcha para que parezca un campamento base en el Everest. Tiempo estimado de creación: 10 minutos.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(47, 'SPA con Rodajas de Pepino', 'El estrés de vigilar la casa es agotador. El elfo se ha tomado un descanso en la mesita de noche; está tumbado sobre una toallita de mano, con un albornoz hecho de papel higiénico y dos rodajas de pepino (o papel verde) sobre sus ojos para reducir el cansancio.' || char(10) || char(10) || 'Materiales: Una toalla pequeña, papel higiénico y dos círculos de cartulina verde o pepino real. Puedes poner música relajante de fondo con un altavoz inteligente para completar la escena matutina. Tiempo estimado de creación: 10 minutos.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"EASY"}]', 0),
(80, 'La Gran Carrera de Peluches', '¡El dormitorio se ha convertido en un circuito de carreras! El elfo ha organizado una competición donde los coches son zapatos y los pilotos son los peluches más rápidos de la habitación. Él está en la meta, agitando una bandera de cuadros y sosteniendo un trofeo dorado.' || char(10) || char(10) || 'Necesitarás varios zapatos de los niños, peluches pequeños, papel para hacer la bandera y un dedal que sirva como trofeo. Alinea los zapatos en el suelo del dormitorio creando una parrilla de salida. Tiempo estimado de creación: 15 minutos.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(81, 'Mensaje con Estrellas Fluorescentes', 'Aprovechando que los niños duermen, el elfo ha pegado estrellas fluorescentes en el techo o en el cabecero de la cama formando un mensaje secreto o su propio nombre. Está colgado del interruptor de la luz, esperando a que apaguen las luces para que su obra brille.' || char(10) || char(10) || 'Materiales: Estrellas de plástico luminiscentes o pegatinas que brillan en la oscuridad. Asegúrate de que las estrellas reciban luz durante el día para que la sorpresa funcione perfectamente por la noche. Tiempo estimado de creación: 20 minutos.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(38, 'Asalto al Joyero de Juguetes', '¡El elfo ha encontrado el tesoro! Se ha metido dentro del joyero o la caja de tesoros de los niños y se ha puesto todos los collares, anillos y coronas de plástico que ha encontrado. Ahora brilla más que el propio árbol de Navidad desde la cómoda del dormitorio.' || char(10) || char(10) || 'Solo necesitas el joyero de los niños y sus accesorios de disfraz. Envuelve al elfo con los collares de cuentas y ponle una tiara si cabe en su cabeza. Es una imagen muy divertida y brillante. Tiempo estimado de creación: 5 minutos.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"TREASURE"},{"label":"EASY"}]', 0),
(148, 'Peluquería Nocturna de Muñecas', 'El elfo ha abierto una peluquería de lujo en el cuarto de juegos. Ha sentado a todas las muñecas en fila y les ha puesto rulos (hechos de pajitas) y capas de peluquería (servilletas). Él está sosteniendo un peine, listo para hacer el cambio de look más radical de la temporada.' || char(10) || char(10) || 'Materiales: Muñecas, pajitas cortadas en trozos pequeños para los rulos, servilletas de papel y un peine pequeño. Puedes añadir un poco de confeti para simular "pelo mágico" cortado. Tiempo estimado de creación: 25 minutos.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"CLOTHES"},{"label":"HARD"}]', 0),
(11, 'Escondite en la Lámpara de Noche', '¡Casi no se le ve! El elfo se ha pegado a la parte interior de la pantalla de la lámpara. Cuando los niños enciendan la luz por la mañana, verán su silueta proyectada a través de la tela, dándoles un susto cariñoso o una sorpresa luminosa para empezar el día.' || char(10) || char(10) || 'Necesitarás cinta adhesiva fuerte (tipo de carrocero para no dañar la lámpara) y colocar al elfo entre la bombilla y la pantalla. ¡Importante! Usa bombillas LED que no emitan calor para evitar cualquier riesgo de quemadura. Tiempo estimado de creación: 5 minutos.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"MYSTERY"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (114, 'Atrapado en la Trituradora de Papel', '¡Emergencia en la oficina de casa! El elfo ha intentado investigar cómo funciona la trituradora de papel y se ha quedado atrapado por la parte inferior de su traje. Con una expresión de pánico absoluto, sostiene un cartel que dice "¡Sacadme de aquí antes de que me convierta en confeti!"' || char(10) || char(10) || 'Materiales necesarios: Una trituradora de papel (¡desenchufada!), unos trozos de papel a medio triturar asomando y un pequeño cartel escrito a mano. Introduce la parte inferior del elfo entre las cuchillas detenidas. Tiempo estimado de creación: 5 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"EASY"}]', 0),
(16, 'El Suelo es Lava: Versión Salón', 'El elfo se ha tomado muy en serio el juego de "El suelo es lava". Ha cruzado todo el salón saltando de mueble en mueble y ahora se encuentra suspendido de un hilo de pescar sobre una alfombra roja que simula el magma volcánico, gritando por un rescate inminente.' || char(10) || char(10) || 'Necesitarás cartulina roja o una manta roja para el suelo, hilo de pescar para colgar al elfo del techo o de una lámpara, y algunos juguetes "atrapados" en la lava a su alrededor. Tiempo estimado de creación: 15 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(69, 'Misión Imposible: El Ventilador de Techo', 'Nuestro agente secreto ha intentado realizar una infiltración aérea usando las aspas del ventilador de techo como plataforma de desembarco. Se encuentra agarrado con una sola mano a una de las aspas, mientras su cuerpo cuelga peligrosamente sobre la mesa del comedor.' || char(10) || char(10) || 'Materiales: Un ventilador de techo (apagado y con el interruptor bloqueado) y un poco de masilla adhesiva para asegurar la mano del elfo al aspa. Asegúrate de que nadie lo encienda por error. Tiempo estimado de creación: 10 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"LIVINGROOM"},{"label":"MEDIUM"}]', 0),
(59, 'Atrapado en el Bote de Galletas', 'La glotonería ha tenido consecuencias catastróficas. El elfo se ha tirado de cabeza al tarro de las galletas y ahora solo se le ven las piernas y el trasero asomando, mientras sus brazos intentan desesperadamente alcanzar una galleta que está al fondo del recipiente de cristal.' || char(10) || char(10) || 'Solo necesitas un tarro de cristal transparente con galletas. Mete al elfo boca abajo de forma que las piernas queden rígidas hacia arriba. Es una de las escenas más graciosas y clásicas de la cocina. Tiempo estimado de creación: 5 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"FOOD"},{"label":"EASY"}]', 0),
(94, 'Duelo en la Tostadora de Acero', '¡Situación de rehén! El elfo ha sido capturado por las pinzas de la tostadora mientras intentaba robar una miga de pan. Está medio metido en la ranura, con un tenedor de juguete en la mano intentando hacer palanca para liberarse antes de que alguien pulse el botón de inicio.' || char(10) || char(10) || 'Materiales: Tostadora (siempre desenchufada), un tenedor de plástico de juguete y algunas migas de pan esparcidas alrededor para dar contexto a su intento de robo. Tiempo estimado de creación: 5 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(6, 'Secuestro por la Banda de los Dinosaurios', 'Los dinosaurios del niño se han rebelado contra la autoridad del Polo Norte. Han atado al elfo a las vías del tren de juguete con cuerdas de lana, y el tren está a solo unos centímetros de distancia. ¡Los niños deben resolver un acertijo para detener la locomotora a tiempo!' || char(10) || char(10) || 'Necesitarás trenes de juguete, figuras de dinosaurios, lana o cordel y una nota con una cuenta atrás o acertijo. Es una escena de acción trepidante para el cuarto de juegos. Tiempo estimado de creación: 20 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(126, 'Cuidado con el Tiburón del Pasillo', 'El elfo ha decidido que el pasillo es un océano peligroso y está intentando cruzarlo montado en un "bote" hecho con un zapato. Sin embargo, un tiburón de plástico le pisa los talones y está a punto de darle un mordisco a la popa de su embarcación.' || char(10) || char(10) || 'Materiales: Un zapato de adulto, una figura de tiburón (o una aleta hecha de cartulina gris) y papel de seda azul para simular el agua alrededor de la escena. Tiempo estimado de creación: 10 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"BATHROOM"},{"label":"MEDIUM"}]', 0),
(34, 'El Laberinto de Cubiertos Afilados', 'En un alarde de temeridad, el elfo ha intentado cruzar el cajón de los cubiertos, pero se ha quedado atrapado entre los dientes de un tenedor gigante y el filo de una espátula. Sostiene un pequeño escudo hecho con un tapón de botella para protegerse del "metal frío".' || char(10) || char(10) || 'Abre ligeramente el cajón de los cubiertos de la cocina y coloca al elfo enredado entre las cucharas y tenedores. Usa un tapón de leche como escudo. Tiempo estimado de creación: 8 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(78, 'Invasión de las Plantas Carnívoras', '¡La planta del salón ha cobrado vida! El elfo ha sido atrapado por las hojas de una maceta y parece que la planta está intentando "engullirlo". El elfo tiene una mano fuera pidiendo ayuda, mientras la otra sostiene un pequeño cuchillo de plástico para defenderse.' || char(10) || char(10) || 'Usa una planta de interior con hojas grandes (o una artificial). Envuelve al elfo entre las hojas y añade unos ojos de papel a la planta para que parezca un monstruo vegetal. Tiempo estimado de creación: 10 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"LIVINGROOM"},{"label":"MEDIUM"}]', 0),
(45, 'Atraco al Banco de Cerdito', 'El elfo ha intentado un asalto de alto riesgo al hucha de cerdito de los niños. Se encuentra colgado de la ranura de las monedas, a punto de caer dentro del oscuro abismo lleno de ahorros, mientras intenta sacar un billete con un imán atado a un hilo.' || char(10) || char(10) || 'Materiales: Una hucha, un billete (real o de juguete), hilo y un pequeño imán o clip. Coloca al elfo con las piernas colgando dentro de la ranura para un efecto máximo de peligro. Tiempo estimado de creación: 12 minutos.', 'elf_danger', '[{"label":"DANGER"},{"label":"TREASURE"},{"label":"HARD"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (141, 'El Chef de los Huevos Sonrientes', '¡Alguien ha estado decorando el desayuno! El elfo ha asaltado la huevera del frigorífico y, con un rotulador mágico, ha dibujado caras divertidas, gafas y bigotes a todos los huevos. Se encuentra sentado en el borde de la caja, orgulloso de su nueva "pandilla" de amigos ovalados.' || char(10) || char(10) || 'Necesitarás una docena de huevos y un rotulador permanente (preferiblemente de punta fina). Dibuja expresiones diferentes en cada huevo y coloca al elfo sosteniendo el rotulador como si acabara de terminar su obra maestra. Tiempo estimado de creación: 15 minutos.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"FOOD"},{"label":"EASY"}]', 0),
(46, 'Pesca de Manzanas en el Bol', 'Inspirado por los juegos de feria, el elfo ha llenado un bol con agua y ha echado varias manzanas. Está intentando "pescarlas" desde el borde usando un tenedor como arpón, aunque parece que está a punto de perder el equilibrio y terminar dándose un chapuzón frutal.' || char(10) || char(10) || 'Materiales: Un bol grande con agua, 3 o 4 manzanas pequeñas y un tenedor de postre. Asegúrate de secar bien los pies del elfo después o usa cinta de doble cara para fijarlo al borde del recipiente. Tiempo estimado de creación: 5 minutos.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"FOOD"},{"label":"EASY"}]', 0),
(13, 'El Tostador-Cama de Lujo', '¿Quién necesita un sofá teniendo una tostadora caliente? El elfo ha metido un par de rebanadas de pan y las ha usado como colchón y manta para echarse una siesta. El olor a pan tostado parece ser su perfume favorito para dormir profundamente en mitad de la encimera.' || char(10) || char(10) || 'Necesitarás dos rebanadas de pan de molde tostadas (deja que se enfríen del todo antes de poner al elfo). Coloca una debajo y otra encima del elfo, asomando solo su cara por un lado. Tiempo estimado de creación: 8 minutos.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"BEDROOM"},{"label":"EASY"}]', 0),
(49, 'Exprimida de Naranjas Gigante', '¡Operación Vitamina C en marcha! El elfo ha intentado hacer zumo para toda la familia, pero la naranja es casi tan grande como él. Se encuentra haciendo fuerza sobre el exprimidor manual, con la cara manchada de pulpa y rodeado de cáscaras por todas partes.' || char(10) || char(10) || 'Materiales: Un exprimidor manual, un par de naranjas cortadas y un vaso pequeño. Pon un poco de zumo real en el vaso para que la escena sea más auténtica y el niño pueda probarlo. Tiempo estimado de creación: 10 minutos.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"FOOD"},{"label":"MEDIUM"}]', 0),
(12, 'Escalada al Tarro de las Chuches', 'El elfo ha divisado el botín prohibido: el tarro de las golosinas en lo alto de la estantería. Ha construido una escalera humana (o de utensilios) usando espátulas y cucharas de madera para alcanzar la cima y darse un festín de azúcar antes de que amanezca.' || char(10) || char(10) || 'Necesitarás varios utensilios de cocina largos y cinta adhesiva para unirlos formando una rampa o escalera. Apóyala contra el estante donde guardes los dulces y pon al elfo a mitad de camino. Tiempo estimado de creación: 15 minutos.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(14, 'Invasión de Hormigas de Chocolate', '¡Un rastro sospechoso cruza la mesa! El elfo está dirigiendo una expedición de "hormigas" hechas de pepitas de chocolate que se dirigen directamente hacia el azucarero. Él va delante con una bandera, guiando a su ejército dulce hacia la victoria gastronómica.' || char(10) || char(10) || 'Materiales: Pepitas de chocolate o pasas, un azucarero y un palillo con un trozo de papel para la bandera. Coloca las pepitas en fila india haciendo curvas por la superficie de la cocina. Tiempo estimado de creación: 10 minutos.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"FOOD"},{"label":"EASY"}]', 0),
(122, 'Lavandería de Cubiertos en el Lavavajillas', 'El elfo ha decidido que los cubiertos no estaban lo suficientemente limpios y se ha metido en el lavavajillas para darles un repaso manual. Está sentado en la cesta de los cubiertos con una esponja diminuta, frotando una cuchara como si fuera un espejo de plata.' || char(10) || char(10) || 'Abre el lavavajillas y coloca al elfo en el compartimento de los cubiertos. Necesitarás un trocito de esponja de cocina y un poco de jabón seco (solo para el efecto visual) sobre un plato cercano. Tiempo estimado de creación: 5 minutos.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"BATHROOM"},{"label":"EASY"}]', 0),
(127, 'El Laboratorio de la Pócima de Colores', 'Algo extraño está pasando con la leche. El elfo ha sacado los colorantes alimentarios y está experimentando en un vaso, creando remolinos de colores psicodélicos. Parece un científico loco buscando la fórmula secreta para que la leche sepa a gominola.' || char(10) || char(10) || 'Necesitarás un vaso de leche y colorante alimentario líquido. Echa unas gotas de diferentes colores (no lo remuevas del todo) y pon al elfo sosteniendo el bote de colorante vacío. Tiempo estimado de creación: 5 minutos.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(28, 'Nieve de Palomitas en el Microondas', '¡Ha habido una explosión de nieve en la cocina! El elfo ha "olvidado" cerrar la bolsa de palomitas y ahora todo el interior del microondas (y parte del mostrador) está cubierto de palomitas blancas y esponjosas. Él está en medio, haciendo un ángel de nieve salado.' || char(10) || char(10) || 'Materiales: Un paquete de palomitas para microondas ya hechas. Espárcelas dentro del aparato y deja que algunas caigan hacia fuera. Coloca al elfo sentado sobre el plato giratorio. Tiempo estimado de creación: 10 minutos.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"SNOW"},{"label":"MEDIUM"}]', 0),
(20, 'Atrapado en el Batidor de Varillas', '¡Ayuda! El elfo intentó batir nata demasiado rápido y se ha quedado enredado entre las varillas metálicas. Sus piernas están cruzadas entre los alambres y sostiene un cuenco vacío sobre su cabeza como si fuera un casco de protección contra salpicaduras.' || char(10) || char(10) || 'Solo necesitas un batidor de varillas manual y un bol pequeño. Introduce con cuidado las piernas del elfo entre las varillas para que se sostenga por sí solo. Es una imagen visualmente muy impactante y divertida. Tiempo estimado de creación: 5 minutos.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (145, 'El Mapa del Tesoro Envejecido', '¡El elfo ha encontrado un mapa antiguo! Se le ve sosteniendo un papel amarillento con bordes quemados que muestra un dibujo de la planta de la casa. Una gran "X" roja marca un lugar secreto donde ha escondido un pequeño detalle para los niños.' || char(10) || char(10) || 'Para esta manualidad, dibuja un mapa simple de tu salón. Moja el papel con una bolsa de té húmeda para darle un tono antiguo y, una vez seco, quema con cuidado los bordes (¡con precaución!). Enrolla el mapa y ponlo en las manos del elfo. Tiempo estimado de creación: 15 minutos.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(44, 'Buceo en el Cofre de Joyas', 'Nuestro aventurero ha asaltado el joyero de mamá o la caja de disfraces. Está sumergido hasta la cintura en una montaña de collares de perlas, pulseras brillantes y anillos de colores, sosteniendo un "diamante" (una piedra de cristal) como si fuera el mayor hallazgo del siglo.' || char(10) || char(10) || 'Solo necesitas colocar al elfo dentro de un joyero abierto. Enreda algunos collares a su alrededor para que parezca que está "nadando" entre joyas. Es una escena visualmente muy atractiva y brillante. Tiempo estimado de creación: 5 minutos.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"CLOTHES"},{"label":"EASY"}]', 0),
(55, 'La Montaña de Monedas de Chocolate', '¡El botín dulce! El elfo ha construido una pirámide perfecta con monedas de chocolate dorado. Está sentado en la cima, protegiendo el tesoro con una espada hecha con un palillo de dientes y un trozo de papel de plata, desafiando a cualquiera que intente llevarse una pieza.' || char(10) || char(10) || 'Necesitarás una red de monedas de chocolate. Apílalas en forma de cono y coloca al elfo arriba. Puedes añadir un pequeño cartel que diga: "Solo para los que se hayan portado bien". Tiempo estimado de creación: 10 minutos.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"FOOD"},{"label":"EASY"}]', 0),
(90, 'X Marca el Lugar en la Nevera', '¡El tesoro está bajo cero! El elfo ha pegado una gran "X" hecha con cinta aislante roja en la puerta de la nevera. Él está pegado justo al lado, señalando la marca con entusiasmo. Dentro de la nevera, en el lugar exacto tras la X, espera una sorpresa fresquita.' || char(10) || char(10) || 'Materiales: Cinta aislante o cartulina roja para la X. Dentro de la nevera puedes esconder un yogur especial, una chocolatina o incluso una pieza de fruta con una cara dibujada. Tiempo estimado de creación: 5 minutos.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(21, 'Pirata en Barco de Papel', '¡Al abordaje! El elfo navega por las aguas del lavabo en un barco de papel hecho con papel de periódico. Lleva un parche en el ojo (dibujado o de papel) y busca el tesoro perdido en el fondo del océano (un anillo o una moneda en el desagüe).' || char(10) || char(10) || 'Haz un barco de papel clásico, pon al elfo dentro y coloca el barco en el lavabo seco o con un poco de algodón azul. No olvides el parche en el ojo para darle el toque pirata definitivo. Tiempo estimado de creación: 10 minutos.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(104, 'Excavación Arqueológica en el Azucarero', 'El elfo cree que hay diamantes ocultos en la cocina. Se le ha encontrado con una cuchara pequeña excavando en el azucarero, dejando un rastro de "arena blanca" por la encimera. Ha encontrado algunas cuentas de collar brillantes enterradas en el azúcar.' || char(10) || char(10) || 'Materiales: Un cuenco con azúcar, una cuchara de café y unas piedrecitas brillantes o cuentas de collar. Entierra los "tesoros" para que los niños puedan ayudarle a terminar la excavación. Tiempo estimado de creación: 10 minutos.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(98, 'El Telescopio de Rollo de Papel', 'Desde lo alto de una estantería, el elfo vigila el horizonte. Está usando un rollo de papel higiénico vacío como telescopio, apuntando directamente hacia el árbol de Navidad, donde ha divisado un paquete que antes no estaba allí.' || char(10) || char(10) || 'Solo necesitas un rollo de cartón vacío. Pégalo a la cara del elfo con un poco de celo para que parezca que está mirando a través de él. Es una forma genial de dirigir la atención de los niños hacia un regalo específico. Tiempo estimado de creación: 5 minutos.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"FESTIVAL"},{"label":"EASY"}]', 0),
(2, 'El Guardián de la Hucha', '¡Intento de robo frustrado! El elfo ha pillado a otro juguete intentando abrir la hucha de los niños. Ahora, el elfo ha montado guardia encima del cerdito de ahorros, rodeándolo con una cadena (un collar de cuentas) y sosteniendo una llave de juguete.' || char(10) || char(10) || 'Usa la hucha de los niños, otro muñeco (como un dinosaurio o un coche) y al elfo encima de la hucha. Es una escena con mucha narrativa que enseña sobre el ahorro. Tiempo estimado de creación: 8 minutos.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"BEDROOM"},{"label":"MEDIUM"}]', 0),
(72, 'Láseres de Seguridad para el Botín', 'El elfo ha robado la caja de galletas y la ha protegido con un sistema de seguridad infrarrojo de alta tecnología. Ha cruzado hilos de lana roja por todo el mueble de la cocina para que nadie pueda acercarse a su tesoro sin activar la alarma.' || char(10) || char(10) || 'Necesitarás lana roja y celo. Cruza los hilos en zigzag delante de un armario o estante donde esté el "tesoro". El elfo debe estar sentado al final del laberinto, custodiando el premio. Tiempo estimado de creación: 20 minutos.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"DANGER"},{"label":"HARD"}]', 0),
(115, 'Reparto de Pegatinas Brillantes', '¡Un tesoro compartido es mejor! El elfo ha abierto un sobre de pegatinas de estrellas doradas y se ha dedicado a pegarlas por toda su ropa y por la frente de los peluches cercanos. Ha dejado el resto de las pegatinas en un plato para que los niños se unan a la fiesta.' || char(10) || char(10) || 'Compra un sobre de pegatinas brillantes (estrellas, corazones o doradas). Pega unas cuantas en el traje del elfo y deja el paquete abierto a su lado. Es un "tesoro" muy fácil de gestionar y muy gratificante. Tiempo estimado de creación: 5 minutos.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"FESTIVAL"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (57, 'El Elfo Camuflado en los Cojines', '¡El juego del escondite ha subido de nivel! El elfo se ha mimetizado con los cojines del sofá. Ha usado un trozo de tela del mismo color que el sofá para taparse hasta la nariz, dejando solo sus ojos traviesos a la vista. ¿Cuánto tardarán los niños en sentarse sobre él?' || char(10) || char(10) || 'Solo necesitas colocar al elfo entre dos cojines grandes y cubrirlo parcialmente con una manta o una funda de cojín similar. Es un reto de observación visual perfecto para empezar el día. Tiempo estimado de creación: 5 minutos.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"EASY"},{"label":"MYSTERY"}]', 0),
(108, 'Sesión de Yoga en la Alfombra', 'Namasté. El elfo ha decidido que necesita un poco de paz interior y ha montado un estudio de yoga en mitad de la alfombra. Está en la posición del "perro boca abajo" sobre una esterilla minúscula, rodeado de piedras decorativas que simulan un jardín zen.' || char(10) || char(10) || 'Materiales: Un trozo de goma eva o fieltro para la esterilla y unas piedras del jardín o velas pequeñas. Coloca al elfo en una postura flexible (sus brazos y piernas suelen ser perfectos para esto). Tiempo estimado de creación: 8 minutos.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"MEDIUM"},{"label":"FESTIVAL"}]', 0),
(51, 'El Escalador de la Cortina', '¡Hazaña vertical! El elfo ha sido avistado a mitad de camino hacia el techo, escalando las cortinas del salón. Lleva una cuerda de seguridad y un pequeño saco a la espalda, como si estuviera intentando alcanzar la barra de la cortina para vigilar la calle desde lo más alto.' || char(10) || char(10) || 'Necesitarás una pinza de la ropa o un clip oculto tras la cortina para sujetar las manos del elfo a la tela. Usa un hilo de lana como cuerda de escalada que cuelgue hasta el suelo. Tiempo estimado de creación: 10 minutos.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(149, 'Tarde de Película y Palomitas', 'El elfo ha tomado el control del mando a distancia. Se le ha encontrado sentado en el reposabrazos del sofá, con el mando entre sus piernas y un cuenco gigante de palomitas (para él) listo para ver sus dibujos favoritos en la televisión.' || char(10) || char(10) || 'Deja el mando de la tele junto al elfo y un pequeño recipiente con palomitas reales. Si puedes dejar la televisión en el menú de una película navideña, el efecto será total. Tiempo estimado de creación: 5 minutos.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"FOOD"},{"label":"EASY"}]', 0),
(130, 'Concierto de Rock con la Guitarra', '¡Hoy hay concierto en directo! El elfo ha encontrado una guitarra (o un ukelele) en el salón y se ha fabricado una púa con un trozo de cartón. Está dando un concierto exclusivo para los peluches, que están todos en primera fila con las manos arriba.' || char(10) || char(10) || 'Usa cualquier instrumento musical que tengas en el salón. Si no tienes, puede usar una raqueta de tenis como "air guitar". Coloca a otros juguetes alrededor como público entregado. Tiempo estimado de creación: 12 minutos.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"FESTIVAL"},{"label":"MEDIUM"}]', 0),
(60, 'El Elfo en el Columpio de Lámpara', '¡Diversión por todo lo alto! El elfo ha fabricado un columpio usando un rollo de cartón y un par de hilos largos, y lo ha colgado de la lámpara de pie del salón. Se balancea felizmente mientras observa el ajetreo de la casa desde el aire.' || char(10) || char(10) || 'Materiales: Un tubo de cartón de papel higiénico cortado por la mitad (como un asiento) y cordel. Ata el columpio a la lámpara (asegúrate de que esté apagada y sea estable). Tiempo estimado de creación: 15 minutos.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(56, 'Paseo en el Coche Teledirigido', '¡Velocidad extrema! El elfo ha "tomado prestado" el coche teledirigido de los niños y está haciendo un rally por la alfombra. Ha montado un circuito con obstáculos (libros, zapatos) y parece que está a punto de batir el récord de velocidad del pasillo.' || char(10) || char(10) || 'Usa un coche de juguete grande donde quepa el elfo. Coloca el mando del coche cerca de sus manos y crea un pequeño circuito de obstáculos por el suelo del salón. Tiempo estimado de creación: 10 minutos.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(24, 'Exposición de Arte en la Mesa', 'El elfo se siente artista. Ha sacado los folios y colores y ha dibujado retratos de toda la familia (con un estilo un poco abstracto). Los tiene todos expuestos en la mesa de centro como si fuera una galería de arte privada.' || char(10) || char(10) || 'Dibuja 3 o 4 dibujos rápidos "estilo elfo" (monigotes divertidos) y pon al elfo con un lápiz de color en la mano. Puedes poner un cartel que diga "Galería de Arte de Navidad". Tiempo estimado de creación: 20 minutos.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(8, 'Pesca de Peces de Papel', 'El elfo ha convertido la pecera (o un bol con agua en el salón) en su lugar de pesca favorito. Con una caña hecha con un lápiz e hilo, está intentando pescar unos peces de colores que él mismo ha recortado de una revista.' || char(10) || char(10) || 'Materiales: Un lápiz, hilo, un clip doblado como anzuelo y peces de papel o cartulina. Pon un poco de celo en los peces para que se peguen al clip cuando los niños jueguen. Tiempo estimado de creación: 15 minutos.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"TREASURE"},{"label":"MEDIUM"}]', 0),
(9, 'Mensaje Secreto en el Marco de Fotos', '¡Hackeo de fotos! El elfo ha abierto un marco de fotos familiar y ha puesto un pequeño bigote y nariz de reno (de quita y pon) sobre el cristal de la foto de los niños. Está sentado sobre el marco, riéndose de su propia broma.' || char(10) || char(10) || 'Usa un rotulador de pizarra blanca (que se borra fácil del cristal) o recortes de papel con un poco de celo. Asegúrate de no dañar la foto original. Es una sorpresa muy graciosa al mirar las fotos de casa. Tiempo estimado de creación: 10 minutos.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"MYSTERY"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, description, imageRes, tags, isFavorite) VALUES (109, 'Baño de Burbujas de Algodón', '¡Relax total! El elfo ha llenado el lavabo hasta arriba con bolas de algodón blanco para simular una bañera de espuma gigante. Está sumergido cómodamente, con un patito de goma al lado y una toallita minúscula enrollada en la cabeza.' || char(10) || char(10) || 'Solo necesitas un paquete de bolas de algodón y el lavabo (asegúrate de que esté seco). Coloca al elfo en medio y añade algún juguete de baño pequeño para completar la escena. Tiempo estimado de creación: 5 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"EASY"}]', 0),
(23, 'Mensaje en el Espejo Empañado', 'El elfo ha dejado un mensaje secreto que solo aparece cuando alguien se ducha. Ha escrito "¡Santa te vigila!" o ha dibujado un árbol de Navidad en el espejo usando un poco de vaho mágico (o jabón).' || char(10) || char(10) || 'Para este truco, escribe en el espejo seco con un bastoncillo mojado en un poco de jabón líquido transparente. Al secarse no se verá, pero cuando el baño se llene de vapor, el mensaje aparecerá por arte de magia. Tiempo estimado de creación: 5 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(140, 'Rápel de Papel Higiénico', '¡Aventura vertical! El elfo ha decidido bajar desde el toallero hasta el suelo usando una larga tira de papel higiénico como cuerda de escalada. Está a mitad de camino, sujeto con fuerza, en una maniobra de descenso digna de un comando.' || char(10) || char(10) || 'Desenrolla una tira larga de papel higiénico desde el soporte y asegura al elfo a ella usando un clip o un poco de celo por detrás. Es una imagen muy impactante y sencilla de hacer. Tiempo estimado de creación: 5 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(27, 'Pesca de Peces en el Inodoro', '¡Peligro, pescador a bordo! El elfo se ha sentado en el borde del inodoro con una caña de pescar hecha con un lápiz e hilo dental. En el extremo del hilo, ha pescado un pececito de gominola o de papel que "nadaba" en las aguas claras.' || char(10) || char(10) || 'Usa un lápiz como caña e hilo dental. Puedes pegar un pez de plástico o papel al hilo. ¡Importante! Asegúrate de que el elfo esté bien sujeto para que no acabe dándose un chapuzón real. Tiempo estimado de creación: 10 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0),
(36, 'Disfraz de Momia de Papel', 'El elfo se ha pasado con el papel higiénico y ha terminado completamente enrollado en él. Parece una pequeña momia navideña que vigila desde la encimera, y solo se le ven sus ojos brillantes asomando por una rendija.' || char(10) || char(10) || 'Envuelve al elfo con cuidado usando tiras de papel higiénico, como si fuera una venda. Puedes usar un par de puntos de celo para que no se desenrolle. Déjalo junto al portacepillos. Tiempo estimado de creación: 10 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"EASY"}]', 0),
(58, 'Guerra de Pasta de Dientes', '¡Alguien ha apretado demasiado el tubo! El elfo ha dejado un rastro de pasta de dientes azul o blanca por el lavabo y ha dibujado "estrellas" con ella. Se le ve con el tapón en la mano, como si estuviera intentando ocultar las pruebas del desastre.' || char(10) || char(10) || 'Usa un poco de pasta de dientes real para crear dibujos simples en el lavabo o sobre una servilleta. Coloca al elfo "manchado" con una pizca de pasta en el traje. Se limpia fácil con agua. Tiempo estimado de creación: 5 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0),
(63, 'Paseo en Barco de Jabonera', 'El elfo ha convertido la jabonera en su barco personal. Navega por la encimera del baño, rodeado de "olas" hechas con toallas azules, buscando el tesoro que se esconde detrás del bote de colonia.' || char(10) || char(10) || 'Usa una jabonera de plástico o madera y coloca al elfo dentro. Usa toallas de color azul o papel de seda para simular el mar alrededor. Es una escena muy creativa. Tiempo estimado de creación: 10 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"TREASURE"},{"label":"MEDIUM"}]', 0),
(71, 'Taller de Maquillaje de Navidad', 'El elfo ha asaltado el neceser y se ha pintado una nariz roja como la de Rudolph usando un poco de pintalabios. También ha intentado maquillar a los cepillos de dientes, poniéndoles lacitos o colores brillantes.' || char(10) || char(10) || 'Usa un poco de colorete o pintalabios (que sea fácil de quitar) para marcar la nariz del elfo. Pon un par de pinceles de maquillaje a su alrededor para decorar la escena. Tiempo estimado de creación: 10 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"CLOTHES"},{"label":"MEDIUM"}]', 0),
(7, 'Esquí Acuático con Cepillos de Dientes', '¡Acción extrema! El elfo está usando dos cepillos de dientes como esquís y se desliza por la rampa del lavabo. Está sujetando el hilo dental como si fuera la cuerda de un barco que lo arrastra a toda velocidad.' || char(10) || char(10) || 'Coloca los pies del elfo sobre las cerdas de dos cepillos de dientes. Usa un trozo largo de hilo dental atado a un grifo para que parezca que está esquiando de verdad. Tiempo estimado de creación: 15 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"ADVENTURE"},{"label":"HARD"}]', 0),
(29, 'Atrapado en el Rollo Infinito', '¡Socorro! El elfo ha empezado a rodar por el pasillo dentro de un rollo de papel higiénico y ha dejado un rastro de metros y metros de papel por todo el suelo del baño. Se encuentra al final del camino, mareado y enredado entre las hojas blancas.' || char(10) || char(10) || 'Desenrolla una buena cantidad de papel higiénico creando un camino desde el soporte hasta la puerta. Pon al elfo al final, envuelto en el último trozo de papel. ¡A los niños les encanta el caos controlado! Tiempo estimado de creación: 10 minutos.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0);